g=[[0]*21 for _ in range(21)]
# input markers
pts={3:[(0,14),(3,17),(5,9),(6,10),(6,13),(8,15),(8,17)],4:[(3,2)],6:[(2,3),(17,3)],7:[(2,6)],1:[(2,7),(17,7)],8:[(13,10),(15,16),(17,13)]}
for c,ps in pts.items():
    for r,k in ps:g[r][k]=c
# complete selected straight segments among identical colors, all lines horizontal/vertical/diagonal
for c,ps in pts.items():
    for i,(r1,k1) in enumerate(ps):
        for r2,k2 in ps[i+1:]:
            dr=r2-r1; dk=k2-k1
            if dr==0 or dk==0 or abs(dr)==abs(dk):
                n=max(abs(dr),abs(dk))
                sr=0 if dr==0 else (1 if dr>0 else -1)
                sk=0 if dk==0 else (1 if dk>0 else -1)
                for t in range(n+1):
                    g[r1+t*sr][k1+t*sk]=c
# expand 7 alongside 1 vertical and 4 alongside 6 vertical
for r in range(2,18):
    if g[r][6]==0:g[r][6]=7
for r in range(3,18):
    if g[r][2]==0:g[r][2]=4
print('\n'.join(' '.join(map(str,row)) for row in g))
print([[(r,c,g[r][c]) for c in range(21) if g[r][c]] for r in range(21)])

